import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

os.makedirs(UPLOAD_DIR, exist_ok=True)

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()

def validate_file_extension(filename):
    if '.' not in filename:
        return False
    ext = filename.rsplit('.', 1)[1].lower()
    return ext in ALLOWED_EXTENSIONS

def convert_document(input_path, output_format='pdf'):
    """Convert document using LibreOffice headless mode"""
    output_dir = os.path.dirname(input_path)
    # Build conversion command
    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {output_dir} {input_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            text=True
        )
        if result.returncode != 0:
            return None, result.stderr

        base = os.path.splitext(os.path.basename(input_path))[0]
        output_path = os.path.join(output_dir, f"{base}.{output_format}")
        if os.path.exists(output_path):
            return output_path, None
        return None, "Conversion produced no output"
    except subprocess.TimeoutExpired:
        return None, "Conversion timed out"

@app.route('/api/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not validate_file_extension(file.filename):
        return jsonify({'error': 'Unsupported file type'}), 415

    output_format = request.form.get('format', 'pdf')

    # Read file content
    content = file.read()
    if len(content) > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 413

    # Save uploaded file
    job_id = generate_job_id(file.filename)
    safe_name = secure_filename(file.filename)
    input_path = os.path.join(UPLOAD_DIR, f"{job_id}_{safe_name}")

    with open(input_path, 'wb') as f:
        f.write(content)

    # Perform conversion
    output_path, error = convert_document(input_path, output_format)

    # Cleanup input
    try:
        os.unlink(input_path)
    except OSError:
        pass

    if error:
        return jsonify({'error': f'Conversion failed: {error}'}), 500

    if output_path and os.path.exists(output_path):
        response = send_file(output_path, as_attachment=True)
        # Schedule cleanup
        @response.call_on_close
        def cleanup():
            try:
                os.unlink(output_path)
            except OSError:
                pass
        return response

    return jsonify({'error': 'Unknown conversion error'}), 500

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'service': 'doc-converter'})

@app.route('/api/formats', methods=['GET'])
def formats():
    return jsonify({
        'input': list(ALLOWED_EXTENSIONS),
        'output': ['pdf', 'html', 'txt', 'epub']
    })

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
